export const Presets: Story = {
  parameters: {
    docs: {
      description: { story: "Place preset buttons next to the calendar in `DatePickerContent`. Setting the value from outside moves the calendar to its month." },
      source: { code: "import * as React from "react";

import { Button } from "@/registry/erbium/ui/button";
import {
  DatePicker,
  DatePickerCalendar,
  DatePickerContent,
  DatePickerInput,
} from "@/registry/erbium/ui/date-picker";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Separator } from "@/registry/erbium/ui/separator";
import { addDays } from "@/registry/erbium/lib/date";

const presets = [
  { days: 0, label: "Today" },
  { days: 1, label: "Tomorrow" },
  { days: 3, label: "In 3 days" },
  { days: 7, label: "In a week" },
  { days: 14, label: "In 2 weeks" },
];

export default function DatePickerPresetsExample() {
  const [date, setDate] = React.useState<Date | undefined>();
  const [open, setOpen] = React.useState(false);

  return (
    <Field className="w-64">
      <FieldLabel htmlFor="date-picker-presets">Remind me</FieldLabel>
      <DatePicker value={date} onValueChange={setDate} open={open} onOpenChange={setOpen}>
        <DatePickerInput id="date-picker-presets" />
        <DatePickerContent className="flex-row gap-group max-sm:flex-col-reverse">
          <div className="flex flex-col gap-0.5">
            {presets.map((preset) => (
              <Button
                key={preset.days}
                variant="ghost"
                size="xs"
                className="justify-start"
                onClick={() => {
                  const today = new Date();

                  setDate(
                    addDays(
                      new Date(today.getFullYear(), today.getMonth(), today.getDate()),
                      preset.days,
                    ),
                  );
                  setOpen(false);
                }}
              >
                {preset.label}
              </Button>
            ))}
          </div>
          <Separator orientation="vertical" className="max-sm:hidden" />
          <Separator className="sm:hidden" />
          <DatePickerCalendar />
        </DatePickerContent>
      </DatePicker>
    </Field>
  );
}
" },
    },
  },
  render: PresetsExample,
};

